    const svg = d3.select("svg");
    const width = +svg.attr("width");
    const height = +svg.attr("height");

    const layers = [
      {radius: 50, color: "#f00"},
      {radius: 100, color: "#0f0"},
      {radius: 150, color: "#00f"},
      {radius: 200, color: "#ff0"},
      {radius: 250, color: "#f0f"},
    ];

    const circles = svg.selectAll("circle")
      .data(layers)
      .join("circle")
      .attr("cx", width / 2)
      .attr("cy", height / 2)
      .attr("r", d => d.radius)
