      .attr("stroke", d => d.color)
      .attr("stroke-width", 2);

    svg.on("mousemove", (event) => {
      const [x, y] = d3.pointer(event);
      const dx = x - width / 2;
      const dy = y - height / 2;
      const distance = Math.sqrt(dx * dx + dy * dy);

      layers.forEach((layer, i) => {
        if (distance > layer.radius - 25 && distance < layer.radius + 25) {
          circles.filter((d, index) => index === i).attr("stroke-width", 4);
